CREATE OR REPLACE PROCEDURE public.sp_record_child_attendance(IN p_id uuid, IN p_tenant_id uuid, IN p_branch_id uuid, IN p_classroom_id uuid, IN p_child_id uuid, IN p_attendance_date date, IN p_status character varying, IN p_arrival_time time without time zone, IN p_departure_time time without time zone, IN p_notes character varying, IN p_recorded_by_user_id uuid, IN p_pickup_person_name character varying, IN p_pickup_person_relationship character varying, IN p_pickup_verification_method character varying, IN p_pickup_notes character varying, IN p_authorized_pickup_id uuid, IN p_departure_verified_by_user_id uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO child_attendance (         id, tenant_id, branch_id, classroom_id, child_id, attendance_date, status,          arrival_time, departure_time, notes, recorded_by_user_id,         pickup_person_name, pickup_person_relationship, pickup_verification_method, pickup_notes, authorized_pickup_id, departure_verified_by_user_id,         created_at, updated_at     )     VALUES (         p_id, p_tenant_id, p_branch_id, p_classroom_id, p_child_id, p_attendance_date, p_status,          p_arrival_time, p_departure_time, p_notes, p_recorded_by_user_id,         p_pickup_person_name, p_pickup_person_relationship, p_pickup_verification_method, p_pickup_notes, p_authorized_pickup_id, p_departure_verified_by_user_id,         CURRENT_TIMESTAMP, CURRENT_TIMESTAMP     )     ON CONFLICT (id) DO UPDATE SET          status = EXCLUDED.status,          arrival_time = EXCLUDED.arrival_time,          departure_time = EXCLUDED.departure_time,          notes = EXCLUDED.notes,         pickup_person_name = EXCLUDED.pickup_person_name,         pickup_person_relationship = EXCLUDED.pickup_person_relationship,         pickup_verification_method = EXCLUDED.pickup_verification_method,         pickup_notes = EXCLUDED.pickup_notes,         authorized_pickup_id = EXCLUDED.authorized_pickup_id,         departure_verified_by_user_id = EXCLUDED.departure_verified_by_user_id,         updated_at = CURRENT_TIMESTAMP; END; $procedure$ ;
